                        self::TYPE_REGION_TAXONOMY_TABS => self::REGION_TAXONOMY_TABS_DEFAULT_LIMIT,
                        self::TYPE_TOUR_TAXONOMY_TABS => self::TOUR_TAXONOMY_TABS_DEFAULT_LIMIT,
